    "remediation": "Set the aws_db_instance.default attribute storage_encrypted = true and optionally specify kms_key_id for a customer-managed KMS key."
  },
  {
    "resource": "aws_db_instance.default",
    "issue": "Backups are disabled",
    "risk": "The database cannot be restored to a recent point in time after ransomware, accidental deletion, or data corruption.",
    "remediation": "Set the aws_db_instance.default attribute backup_retention_period to a value greater than 0, such as 7 or more."
  },
